    'usecases.uc1.title': 'Assistiertes Debuggen',
    'usecases.uc1.body': 'Die KI liest deine IDE, dein Terminal, deine DevTools — schaut sich den tatsächlichen Fehler im Kontext an und schlägt einen Fix vor, den du mit einem Klick anwendest.',
    'usecases.uc2.title': 'Smoke-Tests & QA',
